import { GoogleGenAI } from "@google/genai";
import dotenv from "dotenv";
import fs from "fs/promises"; // Use fs.promises for async file operations
import path from "node:path"; // For resolving file paths
import { fileURLToPath } from "url";

// Load environment variables from .env file
// Adjust the path to your .env file if it's not in the project root
dotenv.config();

// Get __dirname equivalent in ES Modules
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
// --- Configuration ---
// Path to the raw text file generated by web scraping
console.log(__dirname);
const INPUT_FILE_PATH = path.join(__dirname, "pitchport_website_context.txt");
// Path where the JSON file containing chunks and embeddings will be saved
const OUTPUT_FILE_PATH = path.join(__dirname, "website_embeddings.json");

const CHUNK_SIZE = 500; // Max characters per text chunk
const CHUNK_OVERLAP = 50; // Number of characters to overlap between chunks

// Initialize Gemini client for embedding
const ai = new GoogleGenAI(process.env.GEMINI_API_KEY);

/**
 * Loads text content from a specified file path.
 * @param {string} filepath - The path to the text file.
 * @returns {Promise<string|null>} The content of the file as a string, or null if an error occurs.
 */
async function loadTextContent() {
  try {
    const content = await fs.readFile("pitchport_website_context.txt", {
      encoding: "utf8",
    });
    return content;
  } catch (error) {
    console.error(
      `Error loading text content from pitchport_website_context.txt:`,
      error
    );
    return null;
  }
}

/**
 * Splits a given text into smaller, overlapping chunks.
 * @param {string} text - The input text to be chunked.
 * @param {number} chunkSize - The maximum size of each chunk.
 * @param {number} chunkOverlap - The number of characters to overlap between consecutive chunks.
 * @returns {string[]} An array of text chunks.
 */
function splitTextIntoChunks(text, chunkSize, chunkOverlap) {
  if (!text) {
    return [];
  }

  const chunks = [];
  let startIndex = 0;
  while (startIndex < text.length) {
    let endIndex = Math.min(startIndex + chunkSize, text.length);
    let chunk = text.substring(startIndex, endIndex);
    chunks.push(chunk);

    // Move start index for the next chunk, accounting for overlap
    startIndex += chunkSize - chunkOverlap;

    // Break if we've processed the entire text or if the next start index would be invalid
    if (startIndex >= text.length) {
      break;
    }
  }
  return chunks;
}

/**
 * Generates an embedding for a given text chunk using the Gemini Embedding API.
 * @param {string} text - The text chunk to embed.
 * @returns {Promise<number[]|null>} The embedding vector (array of numbers), or null if an error occurs.
 */
async function generateEmbedding(text) {
  try {
    const result = await ai.models.embedContent({
      model: "gemini-embedding-001",
      contents: text,
    });
    return result.embeddings.values; // Returns the array of numbers
  } catch (error) {
    console.error(
      `Error generating embedding for chunk (first 50 chars: "${text.substring(
        0,
        50
      )}...") Error:`,
      error
    );
    // Log the full error if it's an API error for more details
    if (error.response && error.response.data) {
      console.error("API Error Details:", error.response.data);
    }
    return null;
  }
}

/**
 * Orchestrates the process of loading content, chunking, embedding, and saving the results.
 */
async function processContentAndEmbed() {
  console.log(`Starting content processing for RAG from ${INPUT_FILE_PATH}...`);
  const fullText = await loadTextContent("/pitchport_website_context.txt");
  if (!fullText) {
    console.error("Failed to load input text content. Exiting.");
    return;
  }

  console.log(`Loaded ${fullText.length} characters.`);

  const chunks = splitTextIntoChunks(fullText, CHUNK_SIZE, CHUNK_OVERLAP);
  console.log(`Split into ${chunks.length} chunks.`);

  const processedData = [];
  for (let i = 0; i < chunks.length; i++) {
    const chunk = chunks[i];
    console.log(`Generating embedding for chunk ${i + 1}/${chunks.length}...`);
    const embedding = await generateEmbedding(chunk);
    if (embedding) {
      processedData.push({
        id: `chunk_${i}`, // Unique ID for each chunk
        text: chunk,
        embedding: embedding,
      });
    } else {
      console.warn(`Skipping chunk ${i + 1} due to embedding error.`);
    }
  }

  if (processedData.length > 0) {
    try {
      await fs.writeFile(
        OUTPUT_FILE_PATH,
        JSON.stringify(processedData, null, 2),
        { encoding: "utf8" }
      );
      console.log(
        `Successfully processed ${processedData.length} chunks and saved to ${OUTPUT_FILE_PATH}`
      );
    } catch (error) {
      console.error(
        `Error saving processed data to file ${OUTPUT_FILE_PATH}:`,
        error
      );
    }
  } else {
    console.log("No data processed.");
  }
}

// Run the main processing function when the script is executed
processContentAndEmbed();
